export type ProjectDocumentationSectionKind="overview"|"flow"|"matrix"|"profile";
export interface ProjectDocumentationSection {id:string;kind:ProjectDocumentationSectionKind;name:string;targetId?:string;selected:boolean;configuration?:{paths?:readonly string[];contextIds?:readonly string[];columns?:readonly string[];labels?:Readonly<Record<string,string>>}}
